"""Pinned local SearchQA data and the 600-task optimization view."""
from copy import deepcopy
from skilladam.types import BenchmarkCase
from ...storage import read
from . import protocol as p

LOCK_SHA256 = '41b8b1268f5d7d5c4259f685e74bba4f5a415ccdea7814e42782f8c50c7a09a7'
VIEW_SHA256 = '397810ae16545aa600ec770fb8d6d23f90e959c11044590dae1e710a86519a5c'


class SearchQADataset:
    optimization_pool = 'v28_searchqa_train600_v1'
    def __init__(self, root=None, *, batch_size=15):
        from pathlib import Path
        self.root = Path(root or p.ROOT / 'data/searchqa').resolve()
        p.actor_config(batch_size)  # Only the two reviewed schedules are supported.
        self.batch_size = batch_size
        lock_path = self.root / 'v28_dataset.lock.json'
        view_path = self.root / 'v28_train600_v1/manifest.json'
        p.require(p.file_digest(lock_path) == LOCK_SHA256, 'Dataset lock drift')
        p.require(p.file_digest(view_path) == VIEW_SHA256, 'Optimization view drift')
        lock, view = read(lock_path), read(view_path)
        self._hashes = {**lock['sha256'], 'v28_dataset.lock.json': LOCK_SHA256,
                        'v28_train600_v1/manifest.json': VIEW_SHA256}
        self._verify_files()
        self.rows, source_ids = {}, {}
        for split, entry in lock['splits'].items():
            rows = read(self.root / entry['path'])
            p.require(len(rows) == entry['count'], 'Wrong dataset split size')
            source_ids[split] = [row['id'] for row in rows]
            for row in rows:
                p.fields(row, ('id', 'question', 'context', 'answers'), 'Dataset row')
                p.require(row['id'] not in self.rows, 'Duplicate dataset ID')
                self.rows[row['id']] = {**row, 'source_split': split}
        self.splits = {'train': [v['id'] for v in view['optimization_cases']], 'test': view['test_ids']}
        p.require(self.splits['train'] == source_ids['train'] + source_ids['val'] and self.splits['test'] == source_ids['test'], 'Dataset order drift')
        p.require([len(self.splits[k]) for k in ('train', 'test')] == [600, 1400], 'Wrong frozen pool size')
        self.batches = view['batches']
        p.require(len(self.batches) == 40 and all(len(b) == 15 for b in self.batches)
                  and [i for b in self.batches for i in b] == self.splits['train'], 'Batch schedule drift')
        if batch_size == 30:
            self.batches = [self.batches[i] + self.batches[i + 1] for i in range(0, 40, 2)]
        self._identity = {'dataset_id': lock['dataset_id'], 'source_revision': lock['source_revision'],
                          'lock_sha256': LOCK_SHA256, 'view_sha256': VIEW_SHA256}
        self._rows_digest = p.digest(self.rows)
        self._view_digest = p.digest({'splits': self.splits, 'batches': self.batches})
        for task_id in self.rows:
            p.validate_case(self.case(task_id))

    def _verify_files(self):
        for relative, checksum in self._hashes.items():
            p.require(p.file_digest(self.root / relative) == checksum, f'Dataset file drift: {relative}')

    def case(self, task_id):
        row = self.rows[task_id]
        return BenchmarkCase(case_id=task_id,
            payload={k: row[k] for k in ('question', 'context')}, reference=deepcopy(row['answers']),
            metadata={**self._identity, 'source_split': row['source_split'],
                      'split': 'test' if row['source_split'] == 'test' else 'train'})

    def snapshot(self):
        self._verify_files()
        p.require(p.digest(self.rows) == self._rows_digest and
                  p.digest({'splits': self.splits, 'batches': self.batches}) == self._view_digest, 'Bound dataset changed')
        return {**self._identity, 'files_sha256': deepcopy(self._hashes),
                'rows_sha256': self._rows_digest, 'schedule_sha256': self._view_digest}

"""Reviewed standalone SearchQA Prompts; exact user projections and frozen context."""
import json
from pathlib import Path
from src.skill_evolution.v27.benchmark import current
from src.skill_evolution.v27.facts import require
from . import evidence, protocol as p, replay_input_view

PROMPT_VERSIONS={name:f'v28_searchqa_{name}_v1' for name in ('grouping','diagnosis','preconditioner','editor','replay')}
PROMPT_VERSIONS['replay'] = 'v28_searchqa_replay_v2'
RESOURCE_NAMES=frozenset(f'{name}.md' for name in PROMPT_VERSIONS)|{'method_validation_feedback.md'}

def resource_path(key):
    require(key in RESOURCE_NAMES,'Unknown SearchQA Prompt resource')
    return Path(__file__).with_name('prompts')/key

def render(module,background,*,prompt_version=None):
    require(module in PROMPT_VERSIONS,'Unreviewed method module is disabled')
    require(prompt_version in (None,PROMPT_VERSIONS[module]),'Unknown Prompt version')
    p.execution_context(background)
    s=current().resource(f'{module}.md').read_text()
    # Change only the runtime budget description; preserve the method instructions.
    s=s.replace(p.execution_context(p.ACTOR), p.execution_context(background))
    base=p.actor_base_protocol()
    require(s.split('<actor_base_protocol>\n')[1].split('\n</actor_base_protocol>')[0]==base,'Frozen base protocol mismatch')
    require(p.execution_context(background) in s,'Prompt runtime mismatch')
    return s

def prompt_identity(module):
    require(module in PROMPT_VERSIONS,'Unreviewed module')
    return {'prompt_version':PROMPT_VERSIONS[module],'facts_version':p.FACTS_VERSION,
            'input_view':replay_input_view.INPUT_VIEW if module == 'replay' else p.MODEL_INPUT_VIEW,
            'resources_sha256':{name:p.file_digest(current().resource(name)) for name in (f'{module}.md','method_validation_feedback.md')},
            'actor_base_prompt_sha256':p.digest(p.actor_base_protocol())}

def _messages(module,payload,background):
    return [{'role':'system','content':render(module,background)},
            {'role':'user','content':json.dumps(payload,ensure_ascii=False,separators=(',',':'),allow_nan=False)}]

def grouping_messages(saved):
    evidence.validate_saved(saved)
    p.fields(saved['facts'], ('parent', 'runs'), 'Grouping facts')
    runs = saved['facts']['runs']
    require(bool(runs), 'Grouping requires executions')
    for i, run in enumerate(runs, 1):
        evidence.validate_run(run)
        require(run['ref'] == f'P{i}', 'Invalid Parent reference ordering')
    require(len({r['task_id'] for r in runs}) == len(runs), 'Duplicate Grouping task')
    return _messages('grouping', saved['facts'], saved['background'])


def diagnosis_messages(saved):
    return _messages('diagnosis', evidence.diagnosis_input(saved), saved['background'])


def preconditioner_messages(saved):
    return _messages('preconditioner', evidence.preconditioner_model_input(saved), saved['background'])


def editor_messages(saved, adjustments):
    payload = evidence.editor_model_input(saved, adjustments)
    return None if payload is None else _messages('editor', payload, saved['background'])


def replay_messages(bundle):
    return _messages('replay', replay_input_view.model_input(evidence.model_input(bundle)), bundle['background'])

