"""SearchQA single-turn messages with exact, untruncated task text."""
import hashlib
import json
from copy import deepcopy
from pathlib import Path
from ... import validation

PROMPT_PROFILE = 'v28_searchqa_actor_answer_element_words_v1'
SCORER_PROFILE = 'v28_searchqa_skilladam_scoring_v1'
GATE_PROFILE = 'v28_searchqa_em_strict_increase_v1'
CONTEXT = Path(__file__).with_name('context')
ROOT = Path(__file__).resolve().parents[5]
RECORD_VERSION = 'v28_searchqa_execution_v1'
FACTS_VERSION = 'v28_searchqa_facts_v1'
MODEL_INPUT_VIEW = 'v28_searchqa_pairs_content_v1'
FORMAL_CONTEXT = 'searchqa_single_turn_v1'
ACTOR = {'transport': 'direct_http', 'endpoint': 'https://api.deepseek.com/chat/completions',
         'model': 'deepseek-flash', 'max_tokens': 49152, 'temperature': 1.0,
         'reasoning_effort': 'medium', 'thinking': {'type': 'enabled'},
         'timeout_seconds': 300, 'connect_timeout_seconds': 10, 'request_attempts_total': 6,
         'sdk_retries': 0, 'retry_delay_seconds': 1.0, 'retry_policy': 'technical_and_length_shared_six_v1'}


def require(condition, message):
    if not condition:
        raise ValueError(message)


def exact(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False)


def equal(left, right):
    return exact(left) == exact(right)


def digest(value):
    return hashlib.sha256(exact(value).encode()).hexdigest()


def file_digest(path):
    state = validation.current()
    if state is not None:
        state.watch_file(path)
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def fields(value, names, label):
    require(isinstance(value, dict) and set(value) == set(names), f'{label}: unexpected fields')


def background(config):
    require(any(equal(config, actor_config(size)) for size in (15, 30)),
            'Actor differs from a frozen v28 configuration')
    return deepcopy(config)


def actor_config(batch_size=15):
    require(type(batch_size) is int and batch_size in (15, 30), 'Unsupported SearchQA batch size')
    return {**deepcopy(ACTOR), 'max_tokens': 32768 if batch_size == 30 else 49152}


def implementation_identity():
    state = validation.current()
    if state is None:
        return _implementation_identity()
    if 'implementation' not in state.identities:
        state.identities['implementation'] = _implementation_identity()
    return deepcopy(state.identities['implementation'])


def _implementation_identity():
    """Verify pinned dependencies and bind all current v28 execution code."""
    from skilladam.benchmarks.searchqa import evaluation, rollout
    manifest = json.loads(Path(__file__).with_name('source_provenance.json').read_text())
    for relative, expected in manifest['source_sha256'].items():
        require(file_digest(ROOT / relative) == expected, f'Upstream source drift: {relative}')
    for module in (evaluation, rollout):
        relative = f'external/SkillAdam/skilladam/benchmarks/searchqa/{Path(module.__file__).name}'
        require(file_digest(module.__file__) == manifest['source_sha256'][relative], 'Loaded SkillAdam module differs from pinned source')
    local = Path(__file__).resolve().parents[2]
    inherited = json.loads((local / 'v27_contract_sources.json').read_text())['source_sha256']
    for relative, expected in inherited.items():
        require(file_digest(ROOT / relative) == expected, f'Inherited v27 source drift: {relative}')
    return {'prompt': prompt_identity(), 'scorer': SCORER_PROFILE, 'gate': GATE_PROFILE,
            'upstream': deepcopy(manifest['source_sha256']),
            'inherited_v27_sha256': inherited,
            'implementation_sha256': {str(path.relative_to(ROOT)): file_digest(path)
                for path in sorted(local.rglob('*')) if path.suffix in ('.py', '.json', '.md')}}


def actor_base_protocol():
    base = (CONTEXT / 'actor_system.md').read_text().removesuffix('\n').format(skill_section='')
    require(base == (CONTEXT / 'actor_base_protocol.md').read_text().removesuffix('\n'),
            'Method Actor base differs from executable Actor')
    return base


def execution_context(config):
    background(config)
    text = (CONTEXT / 'actor_runtime.md').read_text().removesuffix('\n')
    return text.replace('49,152', f"{config['max_tokens']:,}")


def validate_case(case):
    nonempty_text(case.case_id, 'Task ID')
    fields(case.payload, ('question', 'context'), 'Case payload')
    nonempty_text(case.payload['question'], 'Question')
    nonempty_text(case.payload['context'], 'Context')
    validate_answers(case.reference)
    require(isinstance(case.metadata, dict) and case.metadata.get('split') in ('train', 'test'), 'Invalid case split')
    require(case.metadata.get('source_split') in ('train', 'val', 'test'), 'Invalid source split')
    require((case.metadata['split'] == 'test') == (case.metadata['source_split'] == 'test'), 'Source/effective split mismatch')
    return case


def public_task(case):
    validate_case(case)
    return {'id': case.case_id, 'split': case.metadata['split'], **deepcopy(case.payload)}


def messages(payload, skill):
    return list(build_messages(question=payload['question'], context=payload['context'], skill=skill))


def nonempty_text(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f'{label} must be non-empty text')
    return value


def validate_answers(answers):
    if not isinstance(answers, list) or not answers:
        raise ValueError('Gold answers must be a non-empty list')
    for answer in answers:
        nonempty_text(answer, 'Gold answer')
    return answers


def build_messages(*, question, context, skill):
    nonempty_text(question, 'Question')
    nonempty_text(context, 'Context')
    if skill is not None and not isinstance(skill, str):
        raise ValueError('Skill must be text or None')
    clean_skill = skill.strip() if skill else ''
    section = clean_skill + '\n\n' if clean_skill else ''
    # Remove only the template's terminal LF. Interpolation is single-pass;
    # braces and whitespace inside supplied task/Skill text remain literal.
    state = validation.current()
    def template(name):
        path = CONTEXT / name
        return (state.template(path) if state is not None else path.read_text()).removesuffix('\n')
    system = template('actor_system.md')
    user = template('actor_user.md')
    return (
        {'role': 'system', 'content': system.format(skill_section=section)},
        {'role': 'user', 'content': user.format(context=context, question=question)},
    )


def messages_for_row(row, skill):
    """Validate the reference before execution, but project only task text."""
    if not isinstance(row, dict):
        raise ValueError('Task row must be an object')
    nonempty_text(row.get('id'), 'Task ID')
    validate_answers(row.get('answers'))
    return build_messages(question=row.get('question'), context=row.get('context'), skill=skill)


def prompt_identity():
    return {
        'profile': PROMPT_PROFILE,
        'files_sha256': {
            name: hashlib.sha256((CONTEXT / name).read_bytes()).hexdigest()
            for name in ('actor_system.md', 'actor_user.md')
        },
    }

"""Replay-only display: shared complete initial messages and no duplicate request.

Initial-message sharing is locally ported from v25.2's frozen v25 implementation.
Facts, archives and evidence IDs remain unchanged; no timeline or task encoding.
"""
from copy import deepcopy
import json

from .protocol import require, fields, FORMAL_CONTEXT

FORMAT = 'replay_shared_initial_v1'
INPUT_VIEW = 'v28_searchqa_pairs_shared_initial_v1'


def exact(message):
    # Preserve field order as well as text. Even semantically equivalent objects
    # with different serialization may remain inline rather than lose information.
    return json.dumps(message, ensure_ascii=False, separators=(',', ':'))


def share_initial(view):
    require('shared_initial' not in view, 'Replay initial messages already shared')
    result = deepcopy(view)
    runs = {run['ref']: run for run in result['runs']}
    systems = {}
    for run in result['runs']:
        for message in run['initial']['messages']:
            if message.get('role') == 'system':
                systems.setdefault(exact(message), set()).add(run['ref'])
    table, system_keys = {}, {}
    for run in result['runs']:
        messages = run['initial']['messages']
        for index, message in enumerate(messages):
            if message.get('role') != 'system' or len(systems[exact(message)]) < 2:
                continue
            value = exact(message)
            if value not in system_keys:
                key = f'system_{len(system_keys) + 1}'
                system_keys[value] = key
                table[key] = message
            messages[index] = {'shared_message': system_keys[value]}
    for pair_index, pair in enumerate(result['pairs'], 1):
        p, q = (runs[pair[side]]['initial']['messages'] for side in ('parent', 'candidate'))
        users = [[(i, m) for i, m in enumerate(messages) if m.get('role') == 'user'] for messages in (p, q)]
        if not users[0] or exact([m for _, m in users[0]]) != exact([m for _, m in users[1]]):
            continue
        for user_index, ((pi, message), (qi, _)) in enumerate(zip(*users), 1):
            key = f'pair_{pair_index}_user_{user_index}'
            table[key] = message
            p[pi] = {'shared_message': key}
            q[qi] = {'shared_message': key}
    return {**{key: result[key] for key in ('parent', 'diff', 'plan')},
            'shared_initial': {'format': FORMAT, 'messages': table},
            **{key: result[key] for key in ('pairs', 'runs', 'memory')}}


def restore_initial(view):
    result = deepcopy(view)
    shared = result.pop('shared_initial', None)
    require(isinstance(shared, dict) and set(shared) == {'format', 'messages'}
            and shared['format'] == FORMAT and isinstance(shared['messages'], dict),
            'Invalid Replay shared initial table')
    for run in result['runs']:
        messages = run['initial']['messages']
        for index, message in enumerate(messages):
            if 'shared_message' not in message:
                continue
            key = message['shared_message']
            require(set(message) == {'shared_message'} and isinstance(key, str)
                    and key in shared['messages'], 'Invalid Replay shared message reference')
            restored = shared['messages'][key]
            require(isinstance(restored, dict) and restored.get('role') in ('system', 'user'),
                    'Invalid Replay shared message role')
            messages[index] = deepcopy(restored)
    # Also reject unused entries, cross-pair user sharing and noncanonical pointers.
    require(share_initial(result) == view, 'Noncanonical Replay shared initial view')
    return result


def model_input(view):
    """Project an already verified Replay view; never modify the audit payload."""
    fields(view, ('parent', 'diff', 'plan', 'pairs', 'runs', 'memory'), 'Replay view')
    result = deepcopy(view)
    for run in result['runs']:
        attempts = run['attempts']
        require(isinstance(attempts, list) and len(attempts) == 1,
                'Replay request sharing requires exactly one completed round')
        attempt = attempts[0]
        require(attempt.get('request_context') == FORMAL_CONTEXT,
                'Replay request sharing requires the SearchQA single-turn context')
        require('request_messages' in attempt and
                exact(attempt['request_messages']) == exact(run['initial']['messages']),
                'Replay formal request differs from initial messages')
        del attempt['request_messages']
    return share_initial(result)

"""Native SearchQA metrics, ordinary-content-only parsing and pure EM Gate.

No HTTP or retry loop is provided here. Campaign integration must establish
archive, data, model, prompt and Skill identities before comparing scores.
"""
import math
from skilladam.benchmarks.searchqa.evaluation import best_token_f1, exact_match
from skilladam.benchmarks.searchqa.rollout import extract_answer
from .protocol import nonempty_text, validate_answers


def score(content, gold_answers):
    if not isinstance(content, str):
        raise ValueError('Content must be text')
    validate_answers(gold_answers)
    # Never pass the native extractor an `answer` override or reasoning field.
    prediction, raw = extract_answer({'response': content})
    metrics = {'em': exact_match(prediction, gold_answers),
               'f1': best_token_f1(prediction, gold_answers)}
    validate_metrics(metrics)
    return {'raw_content': raw, 'extracted_answer': prediction}, metrics


def score_response(raw_response, gold_answers):
    """Score a completed API envelope using exactly v27's termination checks.

    RequestFailure propagates unchanged: length/malformed response is retryable;
    refusal/tools are terminal under v27's classification. This function never
    retries, archives, or substitutes a zero score for an incomplete response.
    """
    from ....v27.benchmarks.lmb.actor import parse_response
    validate_answers(gold_answers)
    content, _ = parse_response(raw_response)
    return score(content, gold_answers)


def validate_metrics(metrics):
    if not isinstance(metrics, dict) or set(metrics) != {'em', 'f1'}:
        raise ValueError('Expected em and f1 metrics')
    if type(metrics['em']) not in (int, float) or metrics['em'] not in (0, 1):
        raise ValueError('EM must be binary')
    f1 = metrics['f1']
    if type(f1) not in (int, float) or not math.isfinite(f1) or not 0 <= f1 <= 1:
        raise ValueError('F1 must be finite and within [0, 1]')
    if metrics['em'] == 1 and f1 != 1:
        raise ValueError('Exact match must also have F1=1')
    return metrics


def _indexed_scores(records, expected_ids):
    if not isinstance(expected_ids, list) or not expected_ids:
        raise ValueError('Expected task IDs must be a non-empty list')
    for task_id in expected_ids:
        nonempty_text(task_id, 'Expected task ID')
    if len(set(expected_ids)) != len(expected_ids):
        raise ValueError('Duplicate expected task ID')
    if not isinstance(records, list):
        raise ValueError('Scores must be a list')
    indexed = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'task_id', 'metrics'}:
            raise ValueError('Expected a task_id and completed metrics')
        task_id = nonempty_text(record['task_id'], 'Task ID')
        if task_id in indexed:
            raise ValueError('Duplicate task score')
        indexed[task_id] = validate_metrics(record['metrics'])
    if set(indexed) != set(expected_ids):
        raise ValueError('Incomplete or mismatched task coverage')
    return indexed


def compare_scores(parent, candidate, expected_ids):
    """Pure Gate over complete, provenance-verified per-task score projections.

    F1 is checked for a valid record, but never used in the decision.
    """
    parents = _indexed_scores(parent, expected_ids)
    candidates = _indexed_scores(candidate, expected_ids)
    p = sum(value['em'] == 1 for value in parents.values())
    q = sum(value['em'] == 1 for value in candidates.values())
    return {'decision': 'ACCEPT' if q > p else 'RETAIN',
            'parent_success': p, 'candidate_success': q, 'compared': len(expected_ids)}


def summarize_scores(records, expected_ids):
    """Report macro means only when the entire requested set is complete."""
    indexed = _indexed_scores(records, expected_ids)
    count = len(expected_ids)
    return {'sample_count': count,
            'success_count': sum(m['em'] == 1 for m in indexed.values()),
            'em': sum(indexed[t]['em'] for t in expected_ids) / count,
            'f1': sum(indexed[t]['f1'] for t in expected_ids) / count}

