"""Pure Replay output validation for the SearchQA evidence layer; no generation."""
from src.skill_evolution.v27.facts import require
from src.skill_evolution.v27.contracts.memory import MULTI_KNOWLEDGE_CONTRACT, validate_entries, run_references
from src.skill_evolution.v27.memory_view import knowledge_only, historical_references, check_historical_prose

KNOWLEDGE_INPUT_VIEW = "v28_searchqa_pairs_content_v1"
SUPPORTED_FORMATS = (KNOWLEDGE_INPUT_VIEW,)

def validate_result(result, payload, *, input_view=KNOWLEDGE_INPUT_VIEW, memory_contract=MULTI_KNOWLEDGE_CONTRACT):
    # Full archive validation checks existence and the unchanged output schema first.
    if input_view in SUPPORTED_FORMATS:
        require(memory_contract == MULTI_KNOWLEDGE_CONTRACT, 'Knowledge Only Replay requires multi-Knowledge output')
    validate_entries(result, payload, memory_contract=memory_contract)
    require(input_view in SUPPORTED_FORMATS,
            'Unsupported Replay input view')
    if input_view in SUPPORTED_FORMATS:
        view = knowledge_only(payload['memory'], memory_contract=memory_contract)
        allowed = historical_references(view)
        current = {ref for run in payload['runs'] for ref in run_references(run)}
        contexts = {ref.rsplit('/', 1)[0] for ref in payload['memory']['sources']}
        for entry_index, entry in enumerate(result['entries']):
            for item_index, item in enumerate(entry['knowledge']):
                history = {ref for ref in item['evidence'] if '/' in ref}
                require(history <= allowed, 'Unavailable historical reference in Knowledge evidence')
                check_historical_prose(item['text'], allowed, current=current, historical_contexts=contexts,
                                       location=f'entries[{entry_index}].knowledge[{item_index}].text')
    return result

src/skill_evolution/v28/storage.py:
"""Atomic JSON receipts and read-only freeze checks, following v27 stages."""
from datetime import datetime, timezone
import json
from pathlib import Path


def now():
    return datetime.now(timezone.utc).isoformat()


def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))


def save(path, value):
    path = Path(path)
    data = json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False) + '\n'
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix('.tmp')
    temporary.write_text(data, encoding='utf-8')
    temporary.replace(path)


def freeze(path, value, *, read_only=False):
    from .benchmarks.searchqa.protocol import equal, require
    path = Path(path)
    if path.exists():
        require(equal(read(path), value), f'Frozen value changed: {path}')
    else:
        require(not read_only, f'Missing frozen value: {path}')
        save(path, value)

src/skill_evolution/v28/validation.py:
"""Operation-local evidence validation; never a persistent trust cache.

Only completed archives may be watched. Content hashes and directory membership
are rechecked before the caller receives a successful result. Metadata supplements
content checks (including replacement/restore); it never establishes trust alone.
"""
from contextlib import contextmanager
from contextvars import ContextVar
import hashlib
from pathlib import Path

_ACTIVE = ContextVar('v28_validation_operation', default=None)


def current(adapter=None):
    state = _ACTIVE.get()
    return state if state is not None and (adapter is None or state.adapter is adapter) else None


class ValidationOperation:
    def __init__(self, adapter):
        self.adapter = adapter
        self.files, self.trees = {}, {}
        self.identities, self.templates, self.batches, self.records = {}, {}, {}, {}

    @staticmethod
    def _file(path):
        before = path.stat()
        content = path.read_bytes()
        after = path.stat()
        def identity(s):
            return (s.st_dev, s.st_ino, s.st_size, s.st_mtime_ns, s.st_ctime_ns)
        if identity(before) != identity(after):
            raise ValueError(f'Validation dependency changed while reading: {path}')
        return (identity(after), hashlib.sha256(content).hexdigest()), content

    def watch_file(self, path):
        path = Path(path).absolute()
        if path not in self.files:
            self.files[path] = self._file(path)[0]

    @staticmethod
    def _members(root, source):
        if not root.exists():
            return None
        paths = root.rglob('*')
        if source == 'memory':
            paths = root.glob('*.json')  # Pending .tmp files are not committed dependencies.
        elif source:
            paths = (path for path in paths if path.suffix in ('.py', '.json', '.md'))
        return tuple(sorted(paths))

    def watch_tree(self, root, *, source=False):
        root = Path(root).absolute()
        key = (root, source)
        if key not in self.trees:
            members = self._members(root, source)
            self.trees[key] = members
            for path in members or ():
                if path.is_file():
                    self.watch_file(path)

    def template(self, path):
        path = Path(path).absolute()
        if path not in self.templates:
            fingerprint, content = self._file(path)
            if path in self.files and self.files[path] != fingerprint:
                raise ValueError(f'Validation dependency changed: {path}')
            self.files[path] = fingerprint
            # Match Path.read_text's universal newline handling exactly.
            self.templates[path] = content.decode('utf-8').replace('\r\n', '\n').replace('\r', '\n')
        return self.templates[path]

    def verify(self):
        for (root, source), members in self.trees.items():
            if self._members(root, source) != members:
                raise ValueError(f'Validation dependency membership changed: {root}')
        for path, fingerprint in self.files.items():
            if self._file(path)[0] != fingerprint:
                raise ValueError(f'Validation dependency changed: {path}')


@contextmanager
def operation(adapter):
    """Nest only for the same adapter; discard every cache on exit or failure."""
    active = current(adapter)
    if active is not None:
        yield active
        return
    from .benchmarks.searchqa import protocol as p
    state = ValidationOperation(adapter)
    state.watch_tree(Path(__file__).parent, source=True)
    for group in ('upstream', 'inherited_v27_sha256'):
        for name in adapter._protocol[group]:
            state.watch_file(p.ROOT / name)
    dataset_root = getattr(adapter.dataset, 'root', None)
    if dataset_root is not None:
        state.watch_tree(dataset_root)
    token = _ACTIVE.set(state)
    try:
        adapter._preflight()
        yield state
        # Also recheck mutable bound data/config, independently of file hashes.
        adapter._preflight()
        state.verify()
    finally:
        _ACTIVE.reset(token)
